async function __localSearchFetch(url, options = {}) {
  const query = new URLSearchParams(options.body || '').get('q')?.trim().toLocaleLowerCase() || '';
  const terms = query.split(/\s+/).filter(Boolean);
  const matches = terms.length ? __localSearchEntries.filter(entry => terms.every(term => entry.searchText.toLocaleLowerCase().includes(term))).sort((a, b) => Number(b.title.toLocaleLowerCase().includes(query)) - Number(a.title.toLocaleLowerCase().includes(query))) : [];
  return { json: async () => ({predictiveSearch:{products:matches.slice(0,6),queries:[]},search:{winter2026:matches}}) };
}
